"use client";
import React,{useState} from "react";import Link from "next/link";import api from "@/lib/api";
import {useResource,Table,Badge,Notice,date,button,message} from "@/components/BillingUI";
interface Binding{id:number;router:string;name:string;mac:string;address:string|null;packageName:string|null;expiresAt:string|null;status:string;synced:boolean}
export default function Page(){const {data,loading,error,load}=useResource<Binding>("/api/bindings",true);const [tab,setTab]=useState("ACTIVE");const [note,setNote]=useState("");const remove=async(b:Binding)=>{if(!confirm(`Remove access for ${b.name}?`))return;try{await api.delete(`/api/bindings/${b.id}`);setNote("Removal saved. The router will acknowledge it at its next management sync.");await load();}catch(e){setNote(message(e));}};return <div className="mx-auto max-w-7xl space-y-6"><div className="flex justify-between"><div><h1 className="text-2xl font-semibold text-slate-900">IP bindings</h1><p className="mt-2 text-sm text-slate-500">Manage device bypass access and automatic expiry.</p></div><Link href="/dashboard/bindings/new" className={button}>Bind IP</Link></div><Notice text={error||note}/><div className="flex gap-2">{["ACTIVE","EXPIRED","ALL"].map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg border px-4 py-2 text-xs ${tab===t?"border-blue-200 text-blue-700":"border-slate-300 text-slate-500"}`}>{t} {data.filter(b=>t==="ALL"||b.status===t).length}</button>)}</div><Table rows={data.filter(b=>tab==="ALL"||b.status===tab)} loading={loading} columns={[{label:"Name",render:b=>b.name},{label:"IP",render:b=>b.address||"MAC only"},{label:"MAC",render:b=><Badge>{b.mac}</Badge>},{label:"Router",render:b=>b.router},{label:"Package",render:b=>b.packageName||"Free / internal"},{label:"Status",render:b=><Badge tone={b.status==="ACTIVE"?"green":"red"}>{b.status}</Badge>},{label:"Router sync",render:b=><Badge tone={b.synced?"green":"amber"}>{b.synced?"Acknowledged":"Pending"}</Badge>},{label:"Expiry",render:b=>b.expiresAt?date(b.expiresAt):"Never"},{label:"Action",render:b=><button disabled={b.status==="REMOVED"} onClick={()=>remove(b)} className="text-red-600 disabled:opacity-30">Remove</button>}]}/><p className="text-xs text-slate-500">Pending means the router has not confirmed this configuration. The management agent must be installed; physical enforcement is verified in the later router test.</p></div>;}
